<?php require_once 'includes/auth.php'; require_admin();$counts=[];foreach(['Pending','Assigned','In Progress','Resolved'] as $s){$q=$pdo->prepare('SELECT COUNT(*) c FROM complaints WHERE status=?');$q->execute([$s]);$counts[$s]=(int)$q->fetch()['c'];}$total=array_sum($counts);$q=$pdo->query('SELECT c.*,u.name FROM complaints c JOIN users u ON u.id=c.user_id ORDER BY c.created_at DESC LIMIT 8');$recent=$q->fetchAll();$page_title='Admin Dashboard';include 'includes/header.php';?><div class="page-head"><div><div class="eyebrow">CAMPUS OVERVIEW</div><h1>Dashboard overview</h1><p class="muted">Keep campus issues moving from report to resolution.</p></div><a href="manage_complaints.php" class="btn btn-primary">Manage complaints →</a></div><div class="admin-summary"><div class="summary-main"><span>Total complaints</span><b><?=$total?></b><small>Across all campus reports</small></div><div class="summary-progress"><div><span>Resolution rate</span><b><?=$total?round($counts['Resolved']/$total*100):0?>%</b></div><div class="progress"><span style="width:<?=$total?round($counts['Resolved']/$total*100):0?>%"></span></div><small><?=$counts['Resolved']?> of <?=$total?> resolved</small></div></div><div class="stats-grid"><div class="stat-card"><span class="stat-icon blue">◷</span><div><b><?=$counts['Pending']?></b><span>Pending</span></div></div><div class="stat-card"><span class="stat-icon amber">↗</span><div><b><?=$counts['Assigned']?></b><span>Assigned</span></div></div><div class="stat-card"><span class="stat-icon violet">◌</span><div><b><?=$counts['In Progress']?></b><span>In progress</span></div></div><div class="stat-card"><span class="stat-icon green">✓</span><div><b><?=$counts['Resolved']?></b><span>Resolved</span></div></div></div><div class="section-head"><div><h2>Latest reports</h2><p class="muted">Most recently submitted campus issues.</p></div><a href="manage_complaints.php" class="text-link">View all →</a></div><div class="table-card"><div class="data-table"><div class="tr th"><span>Complaint</span><span>Student</span><span>Location</span><span>Status</span><span></span></div><?php foreach($recent as $c):?><a class="tr" href="complaint.php?id=<?=$c['id']?>"><span><b>#<?=e($c['id'])?></b><small><?=e($c['category'])?> · <?=e(mb_strimwidth($c['description'],0,40,'…'))?></small></span><span><?=e($c['name'])?></span><span><?=e($c['location'])?></span><span><?=status_badge($c['status'])?></span><span class="chevron">›</span></a><?php endforeach;?></div></div><?php include 'includes/footer.php'; ?>
